  `status` tinyint(1) NOT NULL DEFAULT 1,
  `trash` tinyint(1) DEFAULT 0,
  `ext_status` text CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `ext_blob` blob DEFAULT NULL,
  `ext_intext` text CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
